export function extractBearerToken(header: string): string {
  if (header === '') return ''
  const space = header.indexOf(' ')
  if (space < 0) return header
  if (header.slice(0, space).toLowerCase() !== 'bearer') return header
  return header.slice(space + 1).trim()
}

