      ...baseConfig(`http://127.0.0.1:${upstream.port}`, { THYROX_PROXY_MODE: 'multi', THYROX_REDIS_URL: 'redis://placeholder' }),
      rateLimit: { concurrentRequests: 5 },
      sharedState,
    })
    try {
